import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第二十一卦 噬嗑 火雷噬嗑 离上震下","description":"周易 - 第二十一卦 噬嗑 火雷噬嗑 离上震下","frontmatter":{"title":"第二十一卦 噬嗑 火雷噬嗑 离上震下","description":"周易 - 第二十一卦 噬嗑 火雷噬嗑 离上震下"},"headers":[],"relativePath":"zh/classics/zhouyi/022.md","filePath":"zh/classics/zhouyi/022.md"}'),l={name:"zh/classics/zhouyi/022.md"};function t(s,a,n,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="噬嗑" tabindex="-1">噬嗑 <a class="header-anchor" href="#噬嗑" aria-label="Permalink to “噬嗑”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>亨。利用狱。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>颐中有物，曰噬嗑，噬嗑而亨。刚柔分，动而明，雷电合而章。柔得中而上行，虽不当位，利用狱也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>雷电噬嗑；先王以明罚敕法。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>履校灭趾，无咎。象曰：履校灭趾，不行 也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>噬肤灭鼻，无咎。象曰：噬肤灭鼻，乘刚也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>噬腊肉，遇毒；小吝，无咎。象曰：遇毒，位不当也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>噬乾胏，得金矢，利艰贞，吉。象曰：利艰贞吉，未光也。六五：噬乾肉，得黄金，贞厉，无咎。象曰：贞厉无咎，得当也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>何校灭耳，凶。象曰：何校灭耳，聪不明也。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
